"""Small self-contained admin UI for the mailbox sidecar."""

MAILBOX_LOGIN_HTML = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mailbox API Login</title><style>
:root{--bg:#111317;--panel:#1a1e24;--line:#303844;--text:#edf2f7;--muted:#9ba9ba;--accent:#18b6a4;--danger:#ef6b73}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}.login{width:min(360px,calc(100% - 32px));padding:28px;border:1px solid var(--line);border-radius:8px;background:var(--panel)}h1{font-size:20px;margin:0 0 6px}p{color:var(--muted);margin:0 0 20px}label{display:block;font-size:12px;color:var(--muted);margin-bottom:6px}input{width:100%;background:#101419;border:1px solid var(--line);border-radius:5px;padding:10px;color:var(--text);font:inherit}button{width:100%;margin-top:14px;border:0;border-radius:5px;padding:10px;background:var(--accent);color:#06231f;font-weight:700;cursor:pointer}.err{min-height:18px;color:var(--danger);margin-top:10px;font-size:12px}</style></head>
<body><main class="login"><h1>Mailbox API</h1><p>收件与客户取码管理</p><form id="login"><label for="password">管理员密码</label><input id="password" type="password" autocomplete="current-password" required autofocus><button>登录</button><div id="error" class="err"></div></form></main><script>
document.getElementById('login').addEventListener('submit',async e=>{e.preventDefault();const r=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:password.value})});if(r.ok)location='/';else error.textContent='密码错误或服务不可用';});
</script></body></html>"""


MAILBOX_DASHBOARD_HTML = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mailbox API</title><style>
:root{--bg:#111317;--panel:#1a1e24;--panel2:#15191e;--line:#303844;--text:#edf2f7;--muted:#9ba9ba;--accent:#18b6a4;--blue:#4e9de6;--warn:#f2b84b;--danger:#ef6b73;--good:#6ed4a5}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}.shell{width:min(1320px,calc(100% - 32px));margin:auto}.top{min-height:68px;display:flex;align-items:center;gap:16px;border-bottom:1px solid var(--line);margin-bottom:20px}.brand{font-size:20px;font-weight:700}.brand span{color:var(--accent)}.stats{display:flex;gap:14px;margin-left:auto;color:var(--muted);font-size:12px}.stats b{color:var(--text);font-size:15px}.logout{margin-left:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:16px}.wide{margin-bottom:16px}h2{font-size:15px;margin:0 0 14px}h3{font-size:13px;margin:18px 0 10px;color:var(--muted)}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.form-grid .full{grid-column:1/-1}label{display:block;font-size:11px;color:var(--muted);margin-bottom:4px}input,select{width:100%;min-height:34px;border:1px solid var(--line);border-radius:4px;background:#101419;color:var(--text);padding:7px;font:inherit}button{min-height:32px;border:1px solid var(--line);border-radius:4px;background:#232b34;color:var(--text);font:inherit;padding:6px 10px;cursor:pointer}button:hover{border-color:var(--blue)}button.primary{background:var(--accent);border-color:var(--accent);color:#06231f;font-weight:700}button.danger{color:var(--danger)}button.small{min-height:28px;padding:4px 7px;font-size:12px}.actions{display:flex;gap:8px;align-items:end}.hint{font-size:12px;color:var(--muted);margin:8px 0 0}.scroll{overflow:auto;border:1px solid var(--line);border-radius:5px}table{border-collapse:collapse;width:100%;min-width:780px;font-size:12px}th,td{padding:9px;border-bottom:1px solid var(--line);text-align:left;vertical-align:middle}th{color:var(--muted);font-weight:600;background:var(--panel2);white-space:nowrap}tr:last-child td{border-bottom:0}.state{font-size:11px;font-weight:700}.state.ok{color:var(--good)}.state.bad{color:var(--danger)}.state.wait{color:var(--warn)}.token{display:none;position:fixed;inset:0;background:#0009;place-items:center;padding:16px}.token.show{display:grid}.token-box{width:min(640px,100%);background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:20px}.token-box pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#101419;padding:10px;border:1px solid var(--line);border-radius:4px;color:var(--good)}.token-head{display:flex;justify-content:space-between;align-items:center}.notice{min-height:18px;color:var(--warn);font-size:12px;margin:0 0 10px}@media(max-width:760px){.shell{width:min(100% - 20px,1320px)}.top{align-items:flex-start;padding:14px 0;flex-wrap:wrap}.stats{margin-left:0;order:3;width:100%}.grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}}
</style></head><body><div class="shell"><header class="top"><div class="brand">Mailbox <span>API</span></div><div class="stats"><span>别名 <b id="aliasCount">0</b></span><span>API 已启用 <b id="activeCount">0</b></span><span>Profile <b id="profileCount">0</b></span></div><button class="small logout" onclick="logout()">退出</button></header>
<div id="notice" class="notice"></div><section class="grid"><div class="panel"><h2>新增收件 Profile</h2><form id="profileForm"><div class="form-grid"><div><label>显示名称</label><input name="label" required></div><div><label>最终转发邮箱</label><input name="email" type="email" required></div><div><label>IMAP Host</label><input name="imap_host" placeholder="imap.gmail.com" required></div><div><label>端口</label><input name="imap_port" value="993" type="number" required></div><div><label>IMAP 用户名</label><input name="imap_username" required></div><div><label>App 密码 / 授权码</label><input name="imap_password" type="password" required></div><div><label>文件夹</label><input name="folder" value="INBOX"></div><div><label>网络路线</label><select name="network_mode"><option value="direct">直连</option><option value="socks5">SOCKS5 / SOCKS5h</option><option value="http_connect">HTTP CONNECT</option></select></div><div class="full"><label>代理地址（仅非直连）</label><input name="proxy_url" placeholder="socks5h://127.0.0.1:1080"></div></div><div class="actions" style="margin-top:12px"><button class="primary">保存 Profile</button></div></form><p class="hint">IMAP 密码和代理地址仅加密保存，不会在页面重新显示。</p></div><div class="panel"><h2>收件与清理</h2><div class="form-grid"><div><label>邮件保留天数</label><input id="retentionDays" type="number" min="1" max="90"></div><div class="actions"><button onclick="saveRetention()">保存保留期</button></div></div><h3>Profile 同步</h3><div id="profiles" class="scroll"></div><p class="hint">后台每分钟同步一次；客户请求没有新码时，会对对应 Profile 发起一次即时补同步。</p></div></section>
<section class="panel wide"><h2>Apple 主账号默认转发映射</h2><div id="accounts" class="scroll"></div><p class="hint">设置默认 Profile 后，该主账号下未单独覆盖的 HME 都会使用它。不会修改 Apple 官网的转发设置，仅告诉本地服务去哪个邮箱收件。</p></section>
<section class="panel wide"><h2>HME 销售与客户 API</h2><div id="aliases" class="scroll"></div><p class="hint">签发或轮换 Key 后只显示一次。客户 API 只返回 OpenAI 验证码、标题和收到时间。</p></section></div>
<div id="tokenModal" class="token"><div class="token-box"><div class="token-head"><h2>客户 API 凭据</h2><button onclick="closeToken()">关闭</button></div><p class="hint">请立即交付给客户；关闭后无法再次查看此 Key。</p><pre id="tokenContent"></pre><button class="primary" onclick="copyToken()">复制凭据</button></div></div>
<script>
let state={profiles:[],accounts:[],aliases:[]};const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await r.json().catch(()=>({success:false,error:'Invalid response'}));if(!r.ok)throw Error(data.error||data.message||'Request failed');return data}
function profileOptions(selected,empty=true){return (empty?'<option value="">使用主账号默认</option>':'')+state.profiles.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.label)} · ${esc(p.email)}</option>`).join('')}
function render(){ $('aliasCount').textContent=state.aliases.length;$('activeCount').textContent=state.aliases.filter(a=>a.api_active).length;$('profileCount').textContent=state.profiles.length;$('retentionDays').value=state.retention_days;
$('profiles').innerHTML=`<table><thead><tr><th>Profile</th><th>收件邮箱</th><th>路线</th><th>最后同步</th><th>状态</th><th></th></tr></thead><tbody>${state.profiles.map(p=>`<tr><td>${esc(p.label)}</td><td>${esc(p.email)}</td><td>${esc(p.network_mode)}</td><td>${esc(p.last_sync_at||'尚未同步')}</td><td class="${p.last_error?'state bad':'state ok'}">${esc(p.last_error||'正常')}</td><td><button class="small" onclick="syncProfile('${esc(p.id)}')">立即同步</button></td></tr>`).join('')||'<tr><td colspan="6">尚未配置收件 Profile</td></tr>'}</tbody></table>`;
$('accounts').innerHTML=`<table><thead><tr><th>Apple 主账号</th><th>HME 数量</th><th>默认最终转发邮箱</th><th></th></tr></thead><tbody>${state.accounts.map(a=>`<tr><td>${esc(a.source_account)}</td><td>${a.alias_count}</td><td><select id="acc_${esc(a.source_account)}">${profileOptions(a.profile_id,false)||'<option value="">请先创建 Profile</option>'}</select></td><td><button class="small" onclick="saveAccount('${esc(a.source_account)}')">保存</button></td></tr>`).join('')||'<tr><td colspan="4">尚未从 HME 历史发现账号</td></tr>'}</tbody></table>`;
$('aliases').innerHTML=`<table><thead><tr><th>HME</th><th>来源账号</th><th>最终转发覆盖</th><th>客户备注</th><th>到期</th><th>API</th><th>操作</th></tr></thead><tbody>${state.aliases.map(a=>`<tr><td>${esc(a.email)}</td><td>${esc(a.source_account)}</td><td><select id="alias_${esc(a.email)}">${profileOptions(a.profile_id)}</select></td><td><input id="note_${esc(a.email)}" value="${esc(a.buyer_note)}" placeholder="订单 / 客户"></td><td><input id="exp_${esc(a.email)}" value="${esc(a.expires_at)}" placeholder="RFC3339"></td><td><label class="state ${a.api_active?'ok':'wait'}"><input id="active_${esc(a.email)}" type="checkbox" ${a.api_active?'checked':''}> ${a.api_active?'启用':'未启用'}</label></td><td><button class="small" onclick="saveAlias('${esc(a.email)}')">保存</button> <button class="small primary" onclick="issueToken('${esc(a.email)}')">${a.public_id?'轮换 Key':'签发 Key'}</button></td></tr>`).join('')||'<tr><td colspan="7">尚未导入 HME</td></tr>'}</tbody></table>`;}
async function load(){try{state=await api('/api/admin/status');render();$('notice').textContent=''}catch(e){$('notice').textContent=e.message;if(String(e.message).includes('login'))location='/login'}}
async function saveAccount(account){await api('/api/admin/accounts/'+encodeURIComponent(account)+'/profile',{method:'POST',body:JSON.stringify({profile_id:$('acc_'+account).value})});load()}
async function saveAlias(email){await api('/api/admin/aliases/'+encodeURIComponent(email)+'/profile',{method:'POST',body:JSON.stringify({profile_id:$('alias_'+email).value})});await api('/api/admin/aliases/'+encodeURIComponent(email)+'/sales',{method:'POST',body:JSON.stringify({api_active:$('active_'+email).checked,buyer_note:$('note_'+email).value,expires_at:$('exp_'+email).value})});load()}
async function issueToken(email){const d=await api('/api/admin/aliases/'+encodeURIComponent(email)+'/token',{method:'POST'});$('tokenContent').textContent=`API: ${d.api_url}\nAuthorization: ${d.authorization}`;$('tokenModal').classList.add('show');load()}
async function syncProfile(id){try{const d=await api('/api/admin/profiles/'+encodeURIComponent(id)+'/sync',{method:'POST'});$('notice').textContent='同步完成，新增 '+d.imported+' 封验证码邮件';load()}catch(e){$('notice').textContent=e.message}}
async function saveRetention(){await api('/api/admin/settings/retention',{method:'POST',body:JSON.stringify({retention_days:+$('retentionDays').value})});load()}
async function logout(){await api('/api/admin/logout',{method:'POST'});location='/login'}function closeToken(){$('tokenModal').classList.remove('show')}function copyToken(){navigator.clipboard.writeText($('tokenContent').textContent)}
$('profileForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);const payload=Object.fromEntries(f.entries());payload.imap_port=+payload.imap_port;try{await api('/api/admin/profiles',{method:'POST',body:JSON.stringify(payload)});e.target.reset();load()}catch(err){$('notice').textContent=err.message}});load();
</script></body></html>"""
